pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 difficulty, uint8 fuzzSeed) public {
        // Keep timestamp and difficulty in admissible range
        vm.assume(timestamp > 0);
        vm.assume(difficulty > 0);

        // Set block properties to control randomness
        vm.warp(timestamp);
        vm.roll(difficulty);

        // Fund a player and call play()
        address player = address(uint160(uint256(keccak256(abi.encode(fuzzSeed)))));
        vm.deal(player, 10 ether);
        vm.prank(player);
        c.play{value: 10}();

        // General rule: if pot > 0 then a payout did not happen (random != 0 in reference, random != 1 in mutant)
        // Since random is 0 or 1, pot being 0 means a payout occurred and reset it.
        // The invariant: pot is either 0 (payout happened) or 10 (payout didn't happen).
        // In reference, payout on random==0 resets pot; in mutant, payout on random==1 doesn't reset pot.
        // So assert: after play(), if pot != 0 then it must equal TICKET_AMOUNT (10).
        // But the bug makes pot non-zero when it should be zero after a payout.
        // Stronger: pot == 0 || pot == 10 always holds for reference, but mutant can have pot == 10 after payout.
        assertTrue(c.pot() == 0 || c.pot() == 10);
    }
}

