import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 numCalls) public {
        // Bound to a reasonable but wide range of consecutive calls
        numCalls = bound(numCalls, 1, 20);
        address player = address(0x100);
        vm.deal(player, 10 ether);

        uint256 totalSentSinceLastWin = 0;
        uint256 winsHandled = 0;

        for (uint256 i = 0; i < numCalls; i++) {
            vm.prank(player);
            c.play{value: 10}();
            totalSentSinceLastWin += 10;

            // If the player just won, the pot should be reset to 0
            if (c.pot() == 0) {
                winsHandled++;
                totalSentSinceLastWin = 0;
            }
        }

        // Invariant: after any sequence of plays, the pot must NOT exceed
        // the total amount sent since the most recent win.
