import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // We need at least one win. We control block.timestamp and block.difficulty
        // to force a win (random == 0) by making keccak256(timestamp, difficulty) % 2 == 0.
        // We try a small set of valid timestamp/difficulty pairs until one yields a win.
        // The fuzzer provides a seed to explore different attempt orders.

        // Use a fixed caller (we are testing the state invariant, not msg.sender).
        address player = address(0x1234);
        uint256 TICKET = 10;
        vm.deal(player, 10 ether);

        bool won = false;
        uint256 ts = 0;
        uint256 df = 0;
        // Search for a block timestamp and difficulty that produce a win.
        // We limit the search to 256 iterations to keep fuzz runs fast.
        for (uint256 i = 0; i < 256; i++) {
            ts = uint256(keccak256(abi.encode(seed, i, 0)));
            df = uint256(keccak256(abi.encode(seed, i, 1)));
            // Bound to reasonable values to avoid overflow in source or gas issues.
            ts = ts % (type(uint64).max);
            df = df % (type(uint64).max);
            vm.warp(ts);
            vm.roll(df);

            uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (random == 0) {
                won = true;
                break;
            }
        }
        require(won, "Could not find a winning timestamp/difficulty pair");

        vm.startPrank(player);
        c.play{value: TICKET}();

        // The invariant: after a winning play, the pot must be exactly 0
        // because the bank takes FEE_AMOUNT and the player gets the rest.
        // The mutant fails because pot is not reset to 0.
        assertTrue(c.pot() == 0);
        vm.stopPrank();
    }
}

