        // but the invariant we check is deterministic after a single winning play.
        // We restrict the block environment to guarantee a win (random == 0).
        uint256 ts = block.timestamp;
        uint256 diff = block.difficulty;
        // Loop until the random outcome would be 0 for the current timestamp and difficulty.
        // This ensures the next play() call results in a win without external interference.
        while (uint(keccak256(abi.encodePacked(ts, diff))) % 2 != 0) {
