pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 numPlays, uint8 seed) public {
        vm.assume(numPlays > 0 && numPlays <= 10);
        uint256 initialBankBalance = address(c.bank()).balance;
        uint256 initialPot = c.pot();
        uint256 totalTickets = 0;
        uint256 totalWins = 0;
        for (uint8 i = 0; i < numPlays; i++) {
            address player = address(uint160(uint256(keccak256(abi.encodePacked(seed, i)))));
            vm.deal(player, 10 ether);
            vm.warp(block.timestamp + 1);
            vm.roll(block.number + 1);
            vm.prank(player);
            try c.play{value: 10}() {
                totalWins++;
            } catch {
            }
            totalTickets++;
        }
        uint256 finalBankBalance = address(c.bank()).balance;
        uint256 finalPot = c.pot();
        uint256 potChange = finalPot - initialPot;
        uint256 bankChange = finalBankBalance - initialBankBalance;
        assertTrue(finalPot + bankChange == totalTickets * 10 - totalWins * 1);
    }
}
